GRAM = [
("B1", "si + 현재, 현재/미래 — 현실적 가정", "« Si on emprunte, c'est moi qui signe. » « Si tu signes et si ça rate, c'est toi qui paies. » 실현 가능한 가정은 si + 현재형, 결과는 현재·미래. « si » 뒤에 미래형은 쓰지 않는다."),
("B2", "si + 반과거, 조건법 현재 — 가정", "« Si on prenait le local, on pourrait y mettre vingt places. » « Si ça marchait, je serais le plus heureux des hommes. » 현재에 반대되거나 가능성이 낮은 가정. si 절은 반과거, 결과는 조건법 현재."),
("B2", "si + 대과거, 조건법 과거 — 지난 일 가정", "« Si ta mère avait écouté son cœur, elle aurait acheté la boulangerie. » 지나간 일의 가정. si + 대과거 + 조건법 과거(aurait + 과거분사). 후회와 상상을 말할 때 쓴다."),
("B2", "à supposer que + 접속법", "« À supposer que tout aille bien, il faut quand même un plan pour le pire. » 가정을 세울 때 접속법. « Je suppose que » + 직설법과 구별한다."),
("B2", "비교 구문 — plus que, moins de, davantage", "« C'est plus que le loyer. » « Le loyer baisse davantage. » « Ça divise l'investissement par deux. » 배수와 분수 표현: diviser par deux, multiplier par trois."),
("C1", "Et si ~ ? — 제안과 반문", "« Et si ça réussit ? » « Et si M. Arnoux accepte ? » 문두의 et si 는 가정과 제안을 동시에 던진다. 뒤에는 직설법 현재나 반과거가 온다."),
("C1", "pour + 명사 / de peur de + 부정사", "« Pas par peur de rater quelque chose. » 이유를 말할 때 par peur de + 부정사. 긍정 이유는 pour de bonnes raisons. 감정과 이유를 구분하는 표현."),
]

